package dev.unbox.unpvp;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.ScaledResolution;
import net.minecraftforge.client.event.*;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import org.lwjgl.input.Mouse;
import java.util.*;
/** Compact modern friend/world notices; mouse remains captured until the player opens a screen. */
final class SocialNotifications {
 static final class Notice {final String key,id,name,detail;final boolean world;final JsonObject face;Notice(String k,String i,String n,String d,boolean w,JsonObject f){key=k;id=i;name=n;detail=d;world=w;face=f;}}
 private static final Set<String> hidden=new HashSet<>();private static final Map<String,Long> arrivals=new HashMap<>();private static final List<Notice> notices=new ArrayList<>();private static long checked;private static String account="",pending="";private static float unit;private static int left,top;
 static void tick(){long now=System.currentTimeMillis();if(now-checked<500)return;checked=now;String me=SocialBridge.self();if(!me.equals(account)){account=me;hidden.clear();arrivals.clear();pending="";}if(!pending.isEmpty()&&!SocialBridge.pending()){if(SocialBridge.commandSucceeded())hidden.add(pending);pending="";}List<Notice> all=new ArrayList<>();for(JsonObject f:SocialBridge.rows("friends"))if("0".equals(SocialBridge.text(f,"accepted"))&&"incoming".equals(SocialBridge.text(f,"direction")))all.add(new Notice("friend:"+SocialBridge.text(f,"id"),SocialBridge.text(f,"id"),SocialBridge.text(f,"name"),"Friend request",false,f));for(JsonObject i:SocialBridge.worlds()){JsonObject face=new JsonObject();for(JsonObject f:SocialBridge.rows("friends"))if(SocialBridge.text(f,"id").equals(SocialBridge.text(i,"sender")))face=f;all.add(new Notice("world:"+SocialBridge.text(i,"id"),SocialBridge.text(i,"id"),SocialBridge.text(i,"senderName"),SocialBridge.text(i.getAsJsonObject("room"),"name"),true,face));}notices.clear();Set<String> live=new HashSet<>();for(Notice n:all){live.add(n.key);arrivals.putIfAbsent(n.key,now);if(!hidden.contains(n.key)&&(!n.world||!SocialBridge.notificationSeen(n.id)&&now-arrivals.get(n.key)<15000))notices.add(n);}arrivals.keySet().retainAll(live);if(hidden.size()>512)hidden.retainAll(live);}
 static void respond(Notice n,boolean yes){if(!SocialBridge.connected()||SocialBridge.pending())return;if(n.world){if(yes)SocialBridge.join(n.id);else SocialBridge.seen(n.id);hidden.add(n.key);}else if(SocialBridge.command(yes?"accept":"remove",n.id))pending=n.key;checked=0;tick();}
 private static String clip(String s,int n){return s.length()>n?s.substring(0,n-1)+"…":s;}
 @SubscribeEvent public void gui(GuiScreenEvent.DrawScreenEvent.Post e){draw();}
 @SubscribeEvent public void hud(RenderGameOverlayEvent.Post e){if(e.type==RenderGameOverlayEvent.ElementType.ALL&&Minecraft.getMinecraft().currentScreen==null&&!Minecraft.getMinecraft().gameSettings.hideGUI)draw();}
 static void draw(){if(notices.isEmpty())return;ScaledResolution r=new ScaledResolution(Minecraft.getMinecraft());unit=.56f*Math.min(1.15f,Math.min(r.getScaledWidth()/640f,r.getScaledHeight()/360f));left=Math.round(r.getScaledWidth()/unit)-296;top=Math.round(r.getScaledHeight()/unit)-76;Painter.begin(unit,0);try{for(int j=0;j<Math.min(2,notices.size());j++){Notice n=notices.get(j);Painter.opacity=Math.min(1,(System.currentTimeMillis()-arrivals.get(n.key))/160f);int y=top-j*68;Painter.round(left,y,280,60,7,0xef24262d);SocialPanel.Face.draw(n.face,left+12,y+18,24);SolidText.draw(clip(n.name,17),left+44,y+12,13,0xffeeeeee,false);SolidText.draw(clip(n.detail,22),left+44,y+31,12,0xffbbbbbb,false);Painter.round(left+174,y+19,42,23,4,SocialBridge.connected()?0xff4b6595:0xff34373f);Painter.round(left+222,y+19,50,23,4,0xff34373f);Painter.center(pending.equals(n.key)?"…":n.world?"Join":"Accept",left+195,y+26,0xffeeeeee);Painter.center(n.world?"Hide":"Decline",left+247,y+26,0xffdddddd);}}finally{Painter.end();}}
 @SubscribeEvent public void mouse(GuiScreenEvent.MouseInputEvent.Pre e){if(notices.isEmpty()||unit==0)return;Minecraft mc=Minecraft.getMinecraft();ScaledResolution r=new ScaledResolution(mc);float x=Mouse.getEventX()*(float)r.getScaledWidth()/mc.displayWidth/unit-left,y=(r.getScaledHeight()-Mouse.getEventY()*(float)r.getScaledHeight()/mc.displayHeight-1)/unit-top;for(int j=0;j<Math.min(2,notices.size());j++){float row=y+j*68;if(x<0||x>280||row<0||row>60)continue;if(Mouse.getEventButton()==0&&Mouse.getEventButtonState()&&row>=19&&row<=42){if(x>=222&&x<=272)respond(notices.get(j),false);else if(x>=174&&x<=216)respond(notices.get(j),true);}e.setCanceled(true);return;}}
}
